#!/usr/bin/env python3
"""Embed the JSON catalog as a local JS file so the static site also works via file://."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
source = ROOT / "docs" / "data" / "plugins.json"
target = ROOT / "docs" / "data" / "catalog-data.js"
data = json.loads(source.read_text(encoding="utf-8"))
target.write_text(
    "/* Generated by scripts/build_catalog_data.py. Edit plugins.json instead. */\n"
    "window.LAMPA_CATALOG = "
    + json.dumps(data, ensure_ascii=False, indent=2)
    + ";\n",
    encoding="utf-8",
)
print(f"Каталог встроен: {len(data)} записей -> {target.relative_to(ROOT)}")
